#!/usr/bin/env node

import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const GENERATED_HEADER = /^\/\/ @generated by zmdb http-client; contract-format=1; generator=[^\r\n]+\n/;
const FORBIDDEN_RUNTIME_IMPORTS = ['@zmdb/web', '@zmdb/aot-validator', '@zmdb/schema-core', 'typescript'];
const FORBIDDEN_RUNTIME_TERMS = [
  ['TypeIR', /\bTypeIR\b/],
  ['ReflectSession', /\bReflectSession\b/],
  ['TypeScript program creation', /\b(?:createProgram|createIncrementalProgram|createWatchProgram)\b/],
  ['environment access', /\bprocess\.env\b/],
  ['OpenAPI parsing', /\b(?:parseOpenApi|fromOpenApi|OpenAPIParser)\b/i],
];

function parseArguments(argv) {
  const options = {};
  for (let index = 0; index < argv.length; index += 2) {
    const flag = argv[index];
    const value = argv[index + 1];
    if (!['--manifest', '--generated', '--regenerated'].includes(flag) || value === undefined) {
      return {
        error:
          'usage: verify-http-client-boundary.mjs --manifest <package.json> ' +
          '--generated <first.ts> --regenerated <second.ts>',
      };
    }
    options[flag.slice(2)] = resolve(value);
  }
  if (options.manifest === undefined || options.generated === undefined || options.regenerated === undefined) {
    return {
      error:
        'usage: verify-http-client-boundary.mjs --manifest <package.json> ' +
        '--generated <first.ts> --regenerated <second.ts>',
    };
  }
  return { options };
}

function parseManifest(path, problems) {
  if (!existsSync(path)) {
    problems.push(`client manifest is missing: ${path}`);
    return;
  }

  let manifest;
  try {
    manifest = JSON.parse(readFileSync(path, 'utf8'));
  } catch (error) {
    problems.push(`client manifest is not valid JSON: ${error instanceof Error ? error.message : String(error)}`);
    return;
  }

  if (manifest.name !== '@zmdb/client') {
    problems.push(`client manifest name must be "@zmdb/client", received ${JSON.stringify(manifest.name)}`);
  }
  for (const field of ['dependencies', 'peerDependencies']) {
    const entries = typeof manifest[field] === 'object' && manifest[field] !== null ? Object.keys(manifest[field]) : [];
    if (entries.length > 0) {
      problems.push(`@zmdb/client ${field} must be empty, found: ${entries.toSorted().join(', ')}`);
    }
  }
}

function importSpecifiers(source) {
  const specifiers = [];
  for (const [, specifier] of source.matchAll(/(?:^|[\s;])(?:export|import)\b[^;]*?\bfrom\s+['"]([^'"]+)['"]/gm)) {
    specifiers.push(specifier ?? '');
  }
  for (const [, specifier] of source.matchAll(/(?:^|[\s;])import\s+['"]([^'"]+)['"]/gm)) {
    specifiers.push(specifier ?? '');
  }
  for (const [, specifier] of source.matchAll(/\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/gm)) {
    specifiers.push(specifier ?? '');
  }
  return specifiers;
}

function inspectGeneratedSource(path, source, problems) {
  if (!GENERATED_HEADER.test(source)) {
    problems.push(`${path} is missing the fixed contract-format and generator-version header`);
  }
  if (source.includes('\r')) {
    problems.push(`${path} is not LF-only`);
  }

  const specifiers = importSpecifiers(source);
  if (!specifiers.includes('@zmdb/client')) {
    problems.push(`${path} does not import its runtime from @zmdb/client`);
  }
  for (const specifier of specifiers) {
    if (FORBIDDEN_RUNTIME_IMPORTS.some(prefix => specifier === prefix || specifier.startsWith(`${prefix}/`))) {
      problems.push(`${path} imports forbidden runtime boundary "${specifier}"`);
    } else if (specifier.startsWith('node:')) {
      problems.push(`${path} imports Node built-in "${specifier}"`);
    } else if (specifier.startsWith('.') && !specifier.endsWith('.js')) {
      problems.push(`${path} emits relative import "${specifier}" without a .js suffix`);
    } else if (!specifier.startsWith('.') && specifier !== '@zmdb/client') {
      problems.push(`${path} imports non-runtime package "${specifier}"`);
    }
  }

  for (const [label, pattern] of FORBIDDEN_RUNTIME_TERMS) {
    if (pattern.test(source)) {
      problems.push(`${path} contains forbidden ${label}`);
    }
  }

  if (/(?:^|[('"`])(?:\/home\/|\/Users\/|[A-Za-z]:\\|file:\/\/|workspace:)/m.test(source)) {
    problems.push(`${path} contains an absolute, file, or workspace path`);
  }
  if (/https?:\/\/[^/\s:@]+:[^@\s/]+@/i.test(source)) {
    problems.push(`${path} contains credentials in a URL`);
  }
  if (/\b(?:generated\s+at|generatedAt)\b/i.test(source)) {
    problems.push(`${path} contains generation-time entropy`);
  }
  if (
    /\b(?:token|password|secret|apiKey|authorization|cookie|certificate)\b\s*[:=]\s*(['"`])[^'"`\r\n]+\1/i.test(source)
  ) {
    problems.push(`${path} contains a credential-like literal`);
  }
}

export function verifyHttpClientBoundary({ manifest, generated, regenerated }) {
  const problems = [];
  parseManifest(manifest, problems);

  const sources = [];
  for (const path of [generated, regenerated]) {
    if (!existsSync(path)) {
      problems.push(`generated client source is missing: ${path}`);
      sources.push(undefined);
    } else {
      const source = readFileSync(path, 'utf8');
      sources.push(source);
      inspectGeneratedSource(path, source, problems);
    }
  }

  const [first, second] = sources;
  if (first !== undefined && second !== undefined && first !== second) {
    problems.push('two generations from the same contract are not byte-identical');
  }
  return problems;
}

function main() {
  const parsed = parseArguments(process.argv.slice(2));
  if (parsed.error !== undefined) {
    console.error(parsed.error);
    process.exitCode = 2;
    return;
  }
  const problems = verifyHttpClientBoundary(parsed.options);
  if (problems.length > 0) {
    for (const problem of problems) {
      console.error(`[ERROR] ${problem}`);
    }
    process.exitCode = 1;
    return;
  }
  console.log('HTTP client dependency, determinism, generated-source, and secret boundaries verified.');
}

const invokedPath = process.argv[1];
if (invokedPath !== undefined && import.meta.url === pathToFileURL(resolve(invokedPath)).href) {
  main();
}
